//! html5lib-tests `encoding/`: the encoding sniffing cases, as a table of
//! (input bytes, expected encoding name).
//!
//! The `.dat` format: each case is a `#data` line, the input (one or more
//! lines), an `#encoding` line, the expected encoding's name on one line,
//! and a blank line or the end of the file. The input is the bytes between
//! the newline ending `#data` and the newline before `#encoding` (that
//! newline is not part of it), exactly as html5lib's own test runner reads
//! them. Anything else (a missing section, an extra line, text outside a
//! case) is an error, so a changed format fails the conversion.
//!
//! `scripted-tests1.dat` is `encoding/scripted/tests1.dat`: its cases need
//! a script to run (`document.write`), which the parser of this phase
//! never does (the scripting flag is false). It is converted to a count of
//! cases not run, never to passes.

use std::fmt::Write as _;
use std::path::Path;

/// The files vendored for this suite (besides LICENSE.md and SOURCE.md).
pub const FILES: &[&str] = &[
    "scripted-tests1.dat",
    "test-yahoo-jp.dat",
    "tests1.dat",
    "tests2.dat",
];

/// One case: the line of its `#data`, the input and the expected name.
struct Case {
    line: usize,
    data: Vec<u8>,
    encoding: String,
}

/// Split a `.dat` file into its cases.
fn cases(file: &str, bytes: &[u8]) -> Result<Vec<Case>, String> {
    let lines: Vec<&[u8]> = bytes.split(|b| *b == b'\n').collect();
    let mut out = Vec::new();
    let mut i = 0usize;
    // A file ends in a newline, so its last "line" is empty.
    let end = match lines.last() {
        Some(l) if l.is_empty() => lines.len().saturating_sub(1),
        _ => return Err(format!("{file}: does not end in a newline")),
    };
    while i < end {
        let line = i.saturating_add(1);
        if lines.get(i) != Some(&b"#data".as_slice()) {
            return Err(format!("{file}:{line}: expected #data"));
        }
        let start = i.saturating_add(1);
        let Some(at) = (start..end).find(|&k| lines.get(k) == Some(&b"#encoding".as_slice()))
        else {
            return Err(format!("{file}:{line}: #data without #encoding"));
        };
        let data = lines.get(start..at).unwrap_or_default().join(&b'\n');
        let name = lines
            .get(at.saturating_add(1))
            .filter(|_| at.saturating_add(1) < end)
            .ok_or_else(|| format!("{file}:{line}: #encoding without a name"))?;
        let encoding = String::from_utf8(name.to_vec())
            .map_err(|_| format!("{file}:{line}: the encoding name is not UTF-8"))?;
        if encoding.is_empty() || !encoding.is_ascii() {
            return Err(format!("{file}:{line}: bad encoding name {encoding:?}"));
        }
        out.push(Case {
            line,
            data,
            encoding,
        });
        i = at.saturating_add(2);
        // Cases are separated by one blank line; the last may end the file.
        if i < end {
            if lines.get(i).is_some_and(|l| l.is_empty()) {
                i = i.saturating_add(1);
            } else {
                return Err(format!(
                    "{file}:{}: expected a blank line after the case",
                    i.saturating_add(1)
                ));
            }
        }
    }
    Ok(out)
}

/// Convert the suite in `dir` to the body of a Rust source file.
pub fn convert(dir: &Path) -> Result<String, String> {
    let mut out = String::from(
        "// @generated by `cargo xtask testdata` from tests/data/html5lib-encoding/.\n\
         // Do not edit: `cargo xtask verify` fails if this differs from what the\n\
         // converter (xtask/src/testdata/html5lib_encoding.rs) produces.\n\
         // Source, commit and license: tests/data/html5lib-encoding/SOURCE.md.\n\n\
         /// Every case of encoding/*.dat: sniffing `data` (no transport\n\
         /// encoding) gives the encoding named `encoding`.\n\
         const ENCODING: &[Case] = &[\n",
    );
    let mut scripted = 0usize;
    for file in FILES {
        let path = dir.join(file);
        let bytes = std::fs::read(&path).map_err(|e| format!("{}: {e}", path.display()))?;
        let cases = cases(file, &bytes)?;
        if *file == "scripted-tests1.dat" {
            scripted = scripted.saturating_add(cases.len());
            continue;
        }
        for c in cases {
            let data: Vec<String> = c.data.iter().map(|b| format!("0x{b:02X}")).collect();
            writeln!(
                out,
                "    Case {{ file: {file:?}, line: {}, encoding: {:?}, data: &[{}] }},",
                c.line,
                c.encoding,
                data.join(", ")
            )
            .map_err(|e| e.to_string())?;
        }
    }
    writeln!(
        out,
        "];\n\n/// Cases of encoding/scripted/tests1.dat, not run: they need a script\n\
         /// (`document.write`), and this parser runs none.\n\
         const SCRIPTED_NOT_RUN: usize = {scripted};"
    )
    .map_err(|e| e.to_string())?;
    Ok(out)
}
